(* ::Title:: The refined local P2 computation *)

(* ::Section:: Generalities *)

(* ::Text:: Maximum degree of the closed string expansion: *)

DMAX = 4; 

Get["Combinatorica`"]

(* ::Section:: The degree zero prepotential and the topological metric *)

(* ::Text:: The deformed chiral ring is generated by (1,p,p^2), with the relation (p+\[Lambda]1)(p+\[Lambda]2)(p+\[Lambda]3)=0. That is: *)

Replp3 = -Expand[(p + \[Alpha][0])*(p + \[Alpha][1])*(p + \[Alpha][2])] + p^3

(* ::Text:: The degree zero part of the prepotential. The "integrand" reads *)

exp = Simplify[Expand[Expand[Expand[Expand[(t[1] + t[2]*p + t[3]*p^2)^3] /. p^6 -> p^3*Replp3] /. p^5 -> p^2*Replp3] /. p^4 -> p*Replp3] /. p^3 -> Replp3]; 

(* ::Text:: and the integral yields *)

PrepCl = Simplify[Normal[Series[((exp/(\[Alpha][2] - \[Alpha][1])/(\[Alpha][0] - \[Alpha][1])/(-3*p) /. p -> -\[Alpha][1]) + (exp/(\[Alpha][1] - \[Alpha][2])/(\[Alpha][0] - \[Alpha][2])/(-3*p) /. p -> -\[Alpha][2]) + (exp/(\[Alpha][1] - \[Alpha][0])/(\[Alpha][2] - \[Alpha][0])/(-3*p) /. p -> -\[Alpha][0]))/6, {t[1], 0, 3}, {t[2], 0, 3}, {t[3], 0, 3}]]]/\[Epsilon][1]/\[Epsilon][2]; 

(* ::Text:: The topological metric. *)

Clear[\[Eta]]; eta[i_, j_] := Simplify[D[D[D[PrepCl, t[1]], t[i]], t[j]]]

\[Eta] = Array[eta, {3, 3}]; 

MatrixForm[\[Eta]]

(* ::Text:: Rewriting in terms of symmetric polynomials in the weight. *)

\[Eta] = -{{-(1/(3*ee[3]*\[Epsilon][1]*\[Epsilon][2])), 0, 0}, {0, 0, 1/(3*\[Epsilon][1]*\[Epsilon][2])}, {0, 1/(3*\[Epsilon][1]*\[Epsilon][2]), -(ee[1]/(3*\[Epsilon][1]*\[Epsilon][2]))}}

(* ::Text:: Replacement rule for symmetric polynomials in the weight. *)

e\[Alpha][i_] := SymmetricPolynomial[i, Table[\[Alpha][j], {j, 0, 2}]]

(* ::Text:: The inverse tt-metric. *)

\[Eta]m1 = Simplify[Inverse[\[Eta]]]; 

MatrixForm[\[Eta]m1]

(* ::Text:: Non-trivial classical Yukawas which we will need later. *)

C224 = Simplify[D[D[PrepCl, t[3]], {t[2], 2}]]

C222cl = Simplify[D[PrepCl, {t[2], 3}]]

(* ::Section:: Classical canonical coordinates  *)

(* ::Text:: We have: *)

(ReplPToCan = Simplify[Table[p^n -> (-\[Alpha][0])^n*\[Delta][0] + (-\[Alpha][2])^n*\[Delta][2] + (-\[Alpha][1])^n*\[Delta][1], {n, 1, 2}]]; ); ReplCanToP = Flatten[Simplify[Solve[{1, p, p^2} == {\[Delta][1] + \[Delta][2] + \[Delta][0], p /. ReplPToCan, p^2 /. ReplPToCan}, Table[\[Delta][i], {i, 0, 2}]]]]; 

ReplCanToP

Simplify[Sum[\[Delta][i], {i, 0, 2}] /. ReplCanToP]

(* ::Text:: Square lengths of idempotents: *)

cnorm = FullSimplify[Table[Simplify[\[Eta] . CoefficientList[\[Delta][i] /. ReplCanToP, p]][[1]], {i, 0, 2}] /. ee -> e\[Alpha]]

(* ::Section:: The large radius I function *)

ISummand[d_, z_] = z*Product[1/Product[p + \[Alpha][i] + m*z, {m, 1, d}], {i, 0, 2}]*Product[-3*p - m*z, {m, 0, 3*d - 1}]*y^d

IFun[y_] = FullSimplify[y^(p/z)*(z + Sum[ISummand[d, z], {d, 1, Infinity}])]

PFp = Simplify[Series[Block[{coeff = CoefficientList[Series[(z*DY + \[Alpha][0])*(z*DY + \[Alpha][1])*(z*DY + \[Alpha][2]), {DY, 0, 3}], DY], coeff2 = CoefficientList[Series[(3*z*DY)*(3*z*DY + z)*(3*z*DY + 2*z), {DY, 0, 3}], DY]}, Sum[coeff[[n + 1]]*D[IFun[Exp[Y]], {Y, n}], {n, 0, 3}] + y*Sum[coeff2[[n + 1]]*D[IFun[Exp[Y]], {Y, n}], {n, 0, 3}]] /. Y -> Log[y], {y, 0, 4}]]

PFloc = Simplify[Sum[(PFp /. ReplPToCan /. \[Delta][l_] -> KroneckerDelta[l, j])*\[Delta][j], {j, 0, 2}]]

$Assumptions = {z > 0, Element[d, Integers], d >= 0}

II[k_, n_] := Simplify[Coefficient[Collect[SeriesCoefficient[Series[IFun[y], {z, Infinity, 2}], n], p] /. p^3 -> Replp3, p, k]]

C1[y_] = FullSimplify[y*D[II[1, 0], y]]

Simplify[CoefficientList[FullSimplify[SeriesCoefficient[FullSimplify[Series[ISummand[d, z], {z, Infinity, 1}], z > 0 && d > 0 && Element[d, Integers]], 0] /. p -> H /. \[Lambda][i_] -> Subscript[\[Alpha], i], z > 0 && d > 0 && Element[d, Integers]] /. Gamma[x_] -> (x - 1)!, H]]

Simplify[CoefficientList[FullSimplify[SeriesCoefficient[FullSimplify[Series[ISummand[d, z], {z, Infinity, 1}], z > 0 && d > 0 && Element[d, Integers]], 1] /. p -> H /. \[Lambda][i_] -> Subscript[\[Alpha], i], z > 0 && d > 0 && Element[d, Integers]] /. Gamma[x_] -> (x - 1)!, H]]

C2[y_] = y*D[y*(D[II[2, 1], y]/C1[y]), y]; D2[y_] = y*D[y*(D[II[1, 1], y]/C1[y]), y]; 

Simplify[-2*y*(D[y*(D[II[1, 1], y]/C1[y]), y]/(\[Alpha][0] + \[Alpha][1] + \[Alpha][2])) + y*D[y*(D[II[2, 1], y]/C1[y]), y] - 1/(1 + 27*y)]; 

Simplify[Rationalize[N[Series[2*y*(D[y*(D[II[1, 1], y]/C1[y]), y]/(\[Alpha][0] + \[Alpha][1] + \[Alpha][2])), {y, 0, 3}]]]]

L[y_] := (1/(1 + 27*y))^(1/3)

Simplify[Rationalize[N[Series[C2[y] - L[y]^3, {y, 0, 5}]]]]

Simplify[Rationalize[N[Series[(D2[y]/(\[Alpha][0] + \[Alpha][1] + \[Alpha][2]))*2, {y, 0, 5}]]]]

Simplify[%/%%]

Rationalize[N[Series[II[2, 1] - Log[y]^2/2 - Log[y]*(II[1, 0] - Log[y]), {y, 0, 5}]]]

Sum[(9*(-y)^d*(-1 + 3*d)!*(EulerGamma - HarmonicNumber[d] + PolyGamma[0, 3*d]))/d!^3, {d, 1, 5}]

invmm = InverseSeries[Series[Exp[II[1, 0]], {y, 0, 2*DMAX}] /. y -> Q]

dFdt = Series[Normal[Rationalize[N[Series[II[1, 1]*\[Eta][[2,2]] + II[2, 1]*\[Eta][[2,3]] /. ee -> e\[Alpha] /. \[Alpha][ll_] -> \[Epsilon][1]/3 + \[Epsilon][2]/3, {y, 0, 2*DMAX}], 20]]] /. y -> invmm, {Q, 0, 2*DMAX}]

(* ::Subsection:: Relations between L, D2 and C2 *)

Simplify[Rationalize[N[Series[y*D[(II[1, 1]/(\[Alpha][0] + \[Alpha][1] + \[Alpha][2]))*2 - II[2, 1], y] + Log[y]*C1[y], {y, 0, 6}]]]]

Simplify[Rationalize[N[Series[(-Log[L[y]^3])*C1[y], {y, 0, 6}]]]]

Table[Sum[(-(-27*y)^(d - k)/(d - k))*Pochhammer[1/3, k]*(Pochhammer[2/3, k]/k!^2)*(-27*y)^k, {k, 0, d - 1}], {d, 1, 6}]

Simplify[Table[-(((-y)^d*(3*d)!*(1/d + 2*HarmonicNumber[d] + 3*PolyGamma[0, 3*d] - 3*PolyGamma[0, 1 + d]))/d!^3), {d, 1, 6}]]

(* ::Section:: Canonical coordinates *)

C1[y_] = Hypergeometric2F1[1/3, 2/3, 1, -27*y]; L[y_] = (1/(1 + 27*y))^(1/3); CC2[y_] = L[y]^3/C1[y]^2; DD2[y_] = (ee[1]/2)*(CC2[y] - L[y]^3)

(* ::Text:: The fundamental solution. *)

SH[0][z_] := IFun[y]/z; SH[1][z_] := y*(D[IFun[y], y]/C1[y]); SH[2][z_] := (z*y*D[y*(D[IFun[y], y]/C1[y]), y] - DD2[y]*y*(D[IFun[y], y]/C1[y]))/CC2[y]; 

(* ::Text:: Leading order expansion. *)

sH[i_, a_][z_] := KroneckerDelta[i, a] + ssH[i, a][y]/z; 

ssH[i_, 0][y] := PC1[y]*KroneckerDelta[i, 1]; ssH[i_, 1][y] := PD2[y]*KroneckerDelta[i, 1] + PC2[y]*KroneckerDelta[i, 2]; 

Simplify[Series[Normal[Series[Table[Sum[sH[i, a][z]*Inverse[\[Eta]][[a + 1,b + 1]]*sH[j, b][w], {a, 0, 2}, {b, 0, 2}] - Inverse[\[Eta]][[i + 1,j + 1]], {i, 0, 2}, {j, 0, 2}], {w, -z, 0}]], {z, Infinity, 1}]]

Simplify[Solve[Normal[%] == 0, {ssH[2, 2][y], ssH[0, 2][y]}]]

ssH[0, 2][y_] := (-PC1[y])*ee[3]; ssH[2, 2][y_] := PD2[y] - PC2[y]*ee[1]; Normal[Simplify[%%]]

(* ::Text:: Canonical coordinates. Here cch[i,j,k] stands for Subscript[c^i, jk]. *)

dudt[i_, 0] = 1; dudt[i_, 1] = LL[i]/c1[y]; 

Simplify[dudt[i, 1]*dudt[i, 2] - Sum[cch[l, 1, 2]*dudt[i, l], {l, 0, 2}] /. Flatten[Table[cc[0, m, n] -> \[Eta][[m + 1,n + 1]], {m, 0, 2}, {n, 0, 2}]] /. cc[2, 1, 2] -> cc[1, 2, 2]]

Flatten[Simplify[Solve[% == 0, dudt[i, 2]]]]

dudt[i_, 0] = 1; dudt[i_, 1] = LL[i]/c1[y]; dudt[i_, 2] := -((c1[y]*cch[0, 1, 2] + cch[1, 1, 2]*LL[i])/(c1[y]*cch[2, 1, 2] - LL[i]))

(* ::Subsection:: Structure constants *)

(* ::Text:: Structure constants of the small quantum product with at least one identity or divisor insertion. *)

Do[cch[0, i, j] = Inverse[\[Eta]][[1,1]]*\[Eta][[i + 1,j + 1]]; cch[i, 0, j] = KroneckerDelta[i, j], {i, 0, 2}, {j, 0, 2}]; cch[1, 1, 1] = dd2[y]/c1[y]; cch[2, 1, 1] = cc2[y]/c1[y]; cch[2, 1, 2] = (-ee[1])*(cc2[y]/c1[y]) + dd2[y]/c1[y]

(* ::Text:: Zagier-Zinger-type relations. *)

bigrepl = {cc2[y] -> ll[y]^3/c1[y]^2, dd2[y] -> (ee[1]/2)*(cc2[y] - ll[y]^3)}

(* ::Text:: WDVV relations. *)

wdvv = Simplify[Sum[(cch[i, 1, 1]*cch[j, 2, 2] - cch[i, 1, 2]*cch[j, 1, 2])*\[Eta][[i + 1,j + 1]], {i, 0, 2}, {j, 0, 2}] //. bigrepl]

replwdvv = Flatten[Simplify[Solve[wdvv == 0, cch[1, 1, 2]]]]

bigrepl = Join[bigrepl, replwdvv]

(* ::Text:: Semi-semplicity relations. The first one (a=1, b=2) was already implemented. *)

Simplify[dudt[i, 1]*dudt[i, 2] - Sum[cch[l, 1, 2]*dudt[i, l], {l, 0, 2}]]

(* ::Text:: a=b=1. *)

Simplify[Together[dudt[i, 1]^2 - Sum[cch[l, 1, 1]*dudt[i, l], {l, 0, 2}] //. bigrepl]]

solc122 = Flatten[Together[Solve[% == 0, cch[1, 2, 2]]]]

(* ::Text:: The polynomial arising from the leading order solution to the Picard--Fuchs equations. *)

polPF = Sum[ee[j]*XX[3 - j], {j, 1, 3}] + (1/ll[y]^3)*XX[3]

(* ::Text:: Solving for the cubic term. *)

replPF = Flatten[Solve[polPF == 0, XX[3]]]

(* ::Text:: Using this to simplify cch[1,2,2] and get rid of the Subscript[LL, i] dependence. The numerator... *)

Simplify[Block[{coeff = Simplify[CoefficientList[Numerator[cch[1, 2, 2] /. solc122], LL[i]]]}, Sum[coeff[[i]]*XX[i - 1], {i, 1, 4}]] /. replPF]

(* ::Text:: ...divided by the denominator. The final result only depends on cch[2,2,2], c1[y] and ll[y]. *)

Simplify[%/Denominator[cch[1, 2, 2] /. solc122] /. XX[k_] -> LL[i]^k]

solc122 = {cch[1, 2, 2] -> %}

(* ::Text:: Adding this to the list of solutions. *)

bigrepl = Join[Simplify[bigrepl /. solc122], solc122]

(* ::Text:: a = b = 2. We have only cch[2,2,2] left to solve for. *)

Together[dudt[i, 2]^2 - Sum[cch[l, 2, 2]*dudt[i, l], {l, 0, 2}] //. bigrepl]

solc222 = Flatten[Together[Solve[% == 0, cch[2, 2, 2]]]]

(* ::Text:: Once again, we want to get rid of the LL[i] dependence. We have a rational dependence on LL[i] with degrees at numerator and denominator equal to 3. *)

Exponent[Numerator[cch[2, 2, 2] /. solc222], LL[i]]

Exponent[Denominator[cch[2, 2, 2] /. solc222], LL[i]]

(* ::Text:: Replacing the cubic term, numerator and denominator respectively: *)

Simplify[Block[{coeff = Simplify[CoefficientList[Numerator[cch[2, 2, 2] /. solc222], LL[i]]]}, Sum[coeff[[i]]*XX[i - 1], {i, 1, 4}]] /. replPF]

Simplify[Block[{coeff = Simplify[CoefficientList[Denominator[cch[2, 2, 2] /. solc222], LL[i]]]}, Sum[coeff[[i]]*XX[i - 1], {i, 1, 4}]] /. replPF]

(* ::Text:: And all LL[i] dependence magically disappears: *)

solc222 = {Simplify[cch[2, 2, 2] -> %%/% /. XX[k_] -> LL[i]^k]}

bigrepl = Join[Simplify[bigrepl /. solc222], solc222]

(* ::Subsubsection:: Various checks *)

SeriesCoefficient[Series[(z*y*D[y*(D[IFun[y], y]/C1[y]), y] - DD2[y]*y*(D[IFun[y], y]/C1[y]))/CC2[y], {z, Infinity, 1}], 1]; 

tab = CoefficientList[Collect[%, p] /. p^3 -> Replp3, p]; 

