Rationalize[N[Series[tab[[3]], {y, 0, 2}]]]

firstsum = Rationalize[N[Series[II[2, 2], {y, 0, 7}], 20]]; 

Simplify[Rationalize[y*D[y*(D[firstsum, y]/C1[y]), y] - DD2[y]*y*(D[Rationalize[N[Series[II[2, 1], {y, 0, 7}]]], y]/C1[y]) /. ee -> e\[Alpha]]]

Simplify[%/CC2[y]]

y*(D[%, y]/C1[y])

Simplify[%/e\[Alpha][1]]

Simplify[Series[cch[1, 1, 2] /. bigrepl /. c1 -> C1 /. ll[y] -> (1/(1 + 27*y))^(1/3), {y, 0, 3}] /. ee -> e\[Alpha]]

SeriesData[$CellContext`y, 0, {((-Log[$CellContext`y])*$CellContext`\[Alpha][0])*$CellContext`\[Alpha][1] - (Log[$CellContext`y]*$CellContext`\[Alpha][0])*$CellContext`\[Alpha][2] - (Log[$CellContext`y]*$CellContext`\[Alpha][1])*$CellContext`\[Alpha][2], -6*($CellContext`\[Alpha][0]^2 + $CellContext`\[Alpha][1]^2 + $CellContext`\[Alpha][2]^2), 9*(13*$CellContext`\[Alpha][0]^2 + (14*$CellContext`\[Alpha][0])*$CellContext`\[Alpha][1] + 13*$CellContext`\[Alpha][1]^2 + (14*$CellContext`\[Alpha][0])*$CellContext`\[Alpha][2] + (14*$CellContext`\[Alpha][1])*$CellContext`\[Alpha][2] + 13*$CellContext`\[Alpha][2]^2)}, 0, 3, 1]

y*(D[%, y]/C1[y])

