(* ::Section:: Higher genus *)

(* ::Subsection:: Inputting stable graphs *)

(* ::Text:: Load the IGraphM package. *)

Get["IGraphM`"]

SetDirectory[NotebookDirectory[]]

(* ::Text:: Inputs binary data for stable graphs from Boundary. *)

Do[in[k] = Delete[Delete[BinaryReadList[StringJoin["StableGraph-", ToString[k], ".bin"]], 1], -1], {k, 2, 7}]; 

(* ::Text:: Fixing a bug in the input: remove spurious carriage returns (ASCII 13) in genus 6 and 7: *)

in[7] = DeleteCases[in[7], 13]; in[6] = DeleteCases[in[6], 13]; 

(* ::Text:: Inputs a diagonal and upper block; outputs symmetric matrix having those as diagonal and upper-triangular part. *)

tabtoadj[diag__, up__] := Block[{K = Length[diag], Adj, adj}, Adj = Array[adj, {K, K}]; Do[adj[j, j] = diag[[j]]; Do[adj[i, j] = adj[j, i] = up[[j,i - j]], {i, j + 1, K}], {j, 1, K}]; Adj]

(* ::Text:: Inputs raw binary data for each stable graph; outputs a table in the form
{K=number of components, DisplayForm[FormBox[RowBox[{"{", RowBox[{SubscriptBox["g", "1"], ",", "...", ",", " ", SubscriptBox["g", "K"]}], " ", "}"}], TraditionalForm]] = genera/colourings, DisplayForm[FormBox[RowBox[{"{", RowBox[{SubscriptBox["m", "1"], ",", "...", ",", " ", SubscriptBox["m", "K"]}], " ", "}"}], TraditionalForm]] = markings/leaves,  adj= nodes/adjacency matrix} *)

graphlist[raw__] := Block[{count = 1, K, g, m, l, atab, a, out = {}, count2 = 0, adj}, While[count <= Length[raw], If[K == 9 && raw[[count]] > K, count++]; K = raw[[count]]; g = Take[raw, {count + 1, count + K}]; m = Take[raw, {count + K + 1, count + 2*K}]; l = Take[raw, {count + 2*K + 1, count + 3*K}]; a = {}; If[K > 1, atab = Take[raw, {count + 3*K + 1, count + 3*K + K*((K - 1)/2)}]; Do[a = Join[a, {Take[atab, K - j]}]; atab = Delete[atab, Partition[Range[K - j], 1]]; , {j, 1, K - 1}]; ]; adj = tabtoadj[l, a]; AppendTo[out, {K, g, l, adj}]; count += 3*K + Length[Flatten[a]] + 1; count2++; ]; out]

(* ::Text:: Compute the automorphism group of a stable graph, with input as above. As IGBliss can only handle simple graph, the function creates a simple graph by first removing multiple edges (by taking the sign of the adjacency matrix); computes the order of the automorphism group of the corresponding genus-coloured simple graph; the output multiplies that by a factor DisplayForm[FormBox[SubscriptBox["\[Product]", "v"], TraditionalForm]](2^|loops(v)| |loops(v)|! (DisplayForm[FormBox[SubscriptBox["\[Product]", RowBox[{"w", "->", "v"}]], TraditionalForm]]|edges(v->w)|!)) to get the order for the original non-simple stable graph.   *)

aut[tab__] := Block[{a = tab[[-1]], sa, saut}, sa = Sign[a]; saut = IGBlissAutomorphismCount[{AdjacencyGraph[sa], "VertexColors" -> tab[[2]]}]; saut*Product[a[[i,j]]!, {i, 1, Length[a]}, {j, 1, i - 1}]*Product[2^a[[i,i]]*a[[i,i]]!, {i, 1, Length[a]}]]

(* ::Text:: A list sorted by order of automorphism group. It\[CloseCurlyQuote]s pretty inefficient. *)

AbsoluteTiming[Do[grlist[l] = SortBy[graphlist[in[l]], aut], {l, 2, 6}]; ]

(* ::Text:: # of automorphisms in genus two. *)

Table[aut[grlist[2][[i]]], {i, 1, Length[grlist[2]]}]

(* ::Text:: A genus 6 graph. *)

AdjacencyGraph[grlist[6][[-1]][[-1]]]

(* ::Text:: The order of its automorphism group. All nodes have genus zero, so it should be 2^6 6!. *)

aut[grlist[6][[-1]]]

2^6*6!

(* ::Subsection:: Solving exactly in y *)

(* ::Subsubsection:: Picard-Fuchs calculations *)

(* ::Text:: The restriction in the choice of torus action as in Lho\[CloseCurlyQuote]s paper. *)

ee[0] = 1; ee[1] = ee[2]^2/3/ee[3]; 

(* ::Text:: The algebraic relation for the canonical coordinates on the small quantum cohomology locus, arising from the leading order in z of the expansion of the solution of the equivariant PF equation. *)

polPFL[y_, XX_] = polPF /. XX[i_] -> XX^i /. ll -> L

(* ::Text:: The same relation specialised to the fibrewise action Subscript[\[Alpha], i] = (Subscript[\[Epsilon], 1] + Subscript[\[Epsilon], 2])/3: *)

polPFLdiag[y_, XX_] = Simplify[polPF /. XX[i_] -> XX^i /. ll -> L /. ee -> e\[Alpha] /. \[Alpha][ll_] -> \[Epsilon][1]/3 + \[Epsilon][2]/3]

