(* ::Subsubsection:: reprise *)

(* ::Text:: The next function takes exp a rational function in variables (y, var), where var satisfies polPFL[y,var]=0; it reduces it modulo polPFL in the minimal form P[y,var]/Q[y,var] where deg P and deg Q <=2 . *)

LLpowred[exp_, var_] := Block[{temp = Together[exp]}, Factor[Collect[PolynomialRemainder[Numerator[temp], polPFL[y, var], var], var]/Collect[PolynomialRemainder[Denominator[temp], polPFL[y, var], var], var]]]

(* ::Text:: Same, but for the diagonal (fibrewise) restriction of the weights. *)

LLpowreddiag[exp_, var_] := Block[{temp = Together[exp]}, Factor[Collect[PolynomialRemainder[Numerator[temp], polPFLdiag[y, var], var], var]/Collect[PolynomialRemainder[Denominator[temp], polPFLdiag[y, var], var], var]]]

(* ::Text:: A replacement rule expressing the n^th y-derivative of Subscript[L, i], where polPFL[y, Subscript[L, i]] = 0, as a rational function in (y, DisplayForm[FormBox[RowBox[{SubscriptBox["L", "i"], ")"}], TraditionalForm]], presented in the minimal form. *)

LLDerrepl = Simplify[Table[Derivative[l][LLL[i_]][y] -> LLpowred[(ImplRepl[y, LLL[i][y]] /. P -> polPFL)[[l]], LLL[i][y]], {l, 1, 3}]]; 

(* ::Text:: Same, but for the diagonal (fibrewise) restriction of the weights . *)

LLDerrepldiag = Simplify[Table[Derivative[l][LLL[i_]][y] -> LLpowreddiag[(ImplRepl[y, LLL[i][y]] /. P -> polPFLdiag)[[l]], LLL[i][y]], {l, 1, 3}]]; 

(* ::Text:: Cut-off in the z-expansion. *)

ZMAX = 3

(* ::Text:: The asymptotic form of the i^th localised component of the I-function, up to order ZMAX. *)

IAs[y_] = Exp[\[Mu]\[Mu][i][y]/z]*Sum[S0[i, k][y]*z^k, {k, 0, ZMAX + 1}]; 

(* ::Text:: The Picard-Fuchs operator applied to the asymptotic expansion of the I-function. *)

