(* ::Text:: The next routine checks that the Picard-Fuchs equations are effectively satisfied by the ansatz. Takes about half an hour; it\[CloseCurlyQuote]s commented out. *)

Null

(* ::Subsubsection:: The R-matrix *)

(* ::Text:: The square-length of the quantum idempotents.  *)

Factor[3*\[Epsilon][1]*\[Epsilon][2]*ff2[LLL[i][y]]]

(* ::Text:: The lengths, accordingly. *)

sqrt\[CapitalDelta][i_] = Sqrt[\[Epsilon][1]*(\[Epsilon][2]/ee[3])]*(3*ee[3] + ee[2]*LLL[i][y]); sqrt\[CapitalDelta]cl[i] = Sqrt[\[Epsilon][1]*(\[Epsilon][2]/ee[3])]*(3*ee[3] - ee[2]*\[Alpha][i]); 

(* ::Text:: Constructing the R-matrix now. The previous ansatz was not normalised such that Subscript[I, j]/e^(Subscript[u, j][y]/z)(y,z) -> z for y->0. We ensure that this is the case below.   *)

PPunnorm[0, i_][z_] = Simplify[Sum[S0ans[i, k][y]*z^k /. PFAsRepl, {k, 0, ZMAX}] + O[z]^(ZMAX + 1)]; 

normLR[i_, z_] = Sum[cnormLR[i, k]*z^k, {k, 0, ZMAX}]; 

replnormI = Flatten[Solve[(Take[CoefficientList[PPunnorm[0, i][z]*normLR[i, z], z], ZMAX + 1] /. y -> 0 /. LLL[i][0] -> -\[Alpha][i]) == Table[KroneckerDelta[k, 0]/sqrt\[CapitalDelta]cl[i], {k, 0, ZMAX}], Simplify[Table[cnormLR[i, k], {k, 0, ZMAX}]]]]; 

(* ::Text:: So PPunnorm[0,i][z] normLR[i,z] /. replnormI returns the S-matrix acting on the identity (times DisplayForm[FormBox[RowBox[{"diag", "(", SuperscriptBox["e", RowBox[{RowBox[{"-", "u"}], "/", "z"}]]}], TraditionalForm]])). To get the identity column of the R-matrix, we need to normalise by the materialisation constants from quantum Riemann-Roch. *)

replqrr = Block[{ser}, Flatten[Table[qrrc[ll_, k] -> SeriesCoefficient[Series[Exp[Sum[Qrrc[ll, k]*z^(2*k + 1), {k, 0, ZMAX}]], {z, 0, ZMAX + 1}], k], {k, 0, ZMAX + 1}]]]; 

ff[i_][z_] = Normal[Simplify[Series[1 + Sum[qrrc[i, k]*z^k, {k, 1, ZMAX}], {z, 0, ZMAX}]]]

w[i_, j_] := If[j < 3, If[i != j, \[Alpha][j] - \[Alpha][i], 3*\[Alpha][i]], -\[Epsilon][j - 2]]

Qrrc[i_, k_] := (-BernoulliB[2*k + 2]/(2*k + 2)/(2*k + 1))*Sum[1/w[i, j]^(2*k + 1), {j, 0, 4}]

(* ::Text:: The R-matrix applied to the identity, in minimal form, is then: *)

PP[0, i_][z_] = Sum[Simplify[LLpowred[Sum[Coefficient[PPunnorm[0, i][z], z, k]*Coefficient[ff[i][z], z, m]*Coefficient[normLR[i, z], z, l - k - m]*z^l /. replnormI, {k, 0, l}, {m, 0, l}], LLL[i][y]]], {l, 0, ZMAX}]; 

(* ::Text:: I will want to restrict to the fibrewise choice \[Alpha][i]=(\[Epsilon][1]+\[Epsilon][2])/3 of weights now. The tricky bit is that the materialisation constants in ff[i][z] are ill-defined in that case. We need to take that as some sort of limit from the case of isolated fixed points Subscript[\[Alpha], i] != Subscript[\[Alpha], j], and *importantly*, we need to do it without leaving the quartic Subscript[e, 2]^2 = 3*Subscript[e, 1]*Subscript[e, 3] in the weight space as that constraint has been imposed while solving the Picard--Fuchs equations (e.g., DisplayForm[FormBox[RowBox[{SubscriptBox["\[Alpha]", "i"], "="}], TraditionalForm]](\[Epsilon][1]+\[Epsilon][2])/3 + i \[Delta] doesn\[CloseCurlyQuote]t work). It turns out that choosing DisplayForm[FormBox[RowBox[{SubscriptBox["\[Alpha]", "i"], "="}], TraditionalForm]](\[Epsilon][1]+\[Epsilon][2])/(3(1-\[Omega]^i\[Delta])) for \[Omega] = e^(2*Pi*(I/3)) and \[Delta] != 0 does the trick: *)

Simplify[e\[Alpha][2]^2 - 3*e\[Alpha][1]*e\[Alpha][3] /. \[Alpha][i_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*I*(i/3)]*\[Delta])]

(* ::Text:: In the following, I\[CloseCurlyQuote]ll restrict the weights as above and extract the limit as \[Delta] -> 0 of each Taylor coefficient in z of the R-matrix applied to the identity. It turns out to be more expedient to extract leading order in \[Delta] of the numerator and denominator for each coefficient, and to divide the former by the latter. Here goes: *)

Simplify[Series[Numerator[Coefficient[PP[0, 0][z], z, 0]] /. replqrr /. ee -> e\[Alpha] /. \[Alpha][ll_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*(I/3)*ll]*\[Delta]), {\[Delta], 0, 0}]]

Simplify[Series[Denominator[Coefficient[PP[0, 0][z], z, 0]] /. replqrr /. ee -> e\[Alpha] /. \[Alpha][ll_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*(I/3)*ll]*\[Delta]), {\[Delta], 0, 0}]]

FullSimplify[Normal[%%/%]]

cPP[0, i_][0] = % /. LLL[0][y] -> LLL[i][y]; 

cPP[0, i_][0] = Sqrt[3]/(Sqrt[(\[Epsilon][1]*\[Epsilon][2])/(\[Epsilon][1] + \[Epsilon][2])^3]*(\[Epsilon][1] + \[Epsilon][2])^2*(\[Epsilon][1] + \[Epsilon][2] + 3*LLL[0][y])) /. LLL[0][y] -> LLL[i][y]; 

Simplify[Series[Numerator[Coefficient[PP[0, 0][z], z, 1]] /. replqrr /. ee -> e\[Alpha] /. \[Alpha][ll_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*(I/3)*ll]*\[Delta]), {\[Delta], 0, 2}]]

Simplify[Series[Denominator[Coefficient[PP[0, 0][z], z, 1]] /. replqrr /. ee -> e\[Alpha] /. \[Alpha][ll_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*(I/3)*ll]*\[Delta]), {\[Delta], 0, 2}]]

FullSimplify[Normal[%%/%]]

cPP[0, i_][1] = % /. LLL[0][y] -> LLL[i][y]; 

cPP[0, i_][1] = ((1 + 27*y)*(\[Epsilon][1] + \[Epsilon][2] + 3*LLL[0][y])*((\[Epsilon][1] + \[Epsilon][2])*(\[Epsilon][1]^2 - 7*\[Epsilon][1]*\[Epsilon][2] + \[Epsilon][2]^2) + 3*(\[Epsilon][1]^2 - 11*\[Epsilon][1]*\[Epsilon][2] + \[Epsilon][2]^2)*LLL[0][y]))/(108*Sqrt[3]*y*((\[Epsilon][1]*\[Epsilon][2])/(\[Epsilon][1] + \[Epsilon][2])^3)^(3/2)*(\[Epsilon][1] + \[Epsilon][2])^7*((\[Epsilon][1] + \[Epsilon][2])^2 + 9*LLL[0][y]*(\[Epsilon][1] + \[Epsilon][2] + 3*LLL[0][y]))) /. LLL[0][y] -> LLL[i][y]; 

Simplify[Series[Numerator[Coefficient[PP[0, 0][z], z, 2]] /. replqrr /. ee -> e\[Alpha] /. \[Alpha][ll_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*(I/3)*ll]*\[Delta]), {\[Delta], 0, 7}]]

Simplify[Series[Denominator[Coefficient[PP[0, 0][z], z, 2]] /. replqrr /. ee -> e\[Alpha] /. \[Alpha][ll_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*(I/3)*ll]*\[Delta]), {\[Delta], 0, 7}]]

FullSimplify[Normal[%%/%]]

