cPP[0, i_][2] = ((1 + 27*y)*((\[Epsilon][1] + \[Epsilon][2])^2*(8*\[Epsilon][1]*\[Epsilon][2]*(\[Epsilon][1]^2 - 27*\[Epsilon][1]*\[Epsilon][2] + \[Epsilon][2]^2) + 27*y*(\[Epsilon][1]^2 - 7*\[Epsilon][1]*\[Epsilon][2] + \[Epsilon][2]^2)^2) + 3*(\[Epsilon][1] + \[Epsilon][2])*(81*y*\[Epsilon][1]^4 + 2*(8 - 675*y)*\[Epsilon][1]^3*\[Epsilon][2] + (-496 + 8235*y)*\[Epsilon][1]^2*\[Epsilon][2]^2 + 2*(8 - 675*y)*\[Epsilon][1]*\[Epsilon][2]^3 + 81*y*\[Epsilon][2]^4)*LLL[0][y] + 9*(81*y*\[Epsilon][1]^4 + 2*(4 - 783*y)*\[Epsilon][1]^3*\[Epsilon][2] + (-280 + 14067*y)*\[Epsilon][1]^2*\[Epsilon][2]^2 + 2*(4 - 783*y)*\[Epsilon][1]*\[Epsilon][2]^3 + 81*y*\[Epsilon][2]^4)*LLL[0][y]^2))/(2592*Sqrt[3]*y*((\[Epsilon][1]*\[Epsilon][2])/(\[Epsilon][1] + \[Epsilon][2])^3)^(5/2)*(\[Epsilon][1] + \[Epsilon][2])^11*((-2 + 27*y)*(\[Epsilon][1] + \[Epsilon][2])^2 + 3*LLL[0][y]*((-5 + 108*y)*(\[Epsilon][1] + \[Epsilon][2]) + 9*(-1 + 54*y)*LLL[0][y]))) /. LLL[0][y] -> LLL[i][y]; 

(* ::Text:: The cubic order requires more muscle in the calculation of the denominator. The below uses a trick to distribute the calculation in parallel to speed it up. *)

Numerator[Coefficient[PP[0, 0][z], z, 3]] /. replqrr /. ee -> e\[Alpha] /. \[Alpha][ll_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*(I/3)*ll]*\[Delta]); 

Block[{prefactor, arg, out}, prefactor = %[[1]]; arg = %[[2]]; DistributeDefinitions[arg]; If[Head[arg] == Plus, out = Simplify[prefactor*ParallelSum[Simplify[SeriesCoefficient[Series[arg[[k]], {\[Delta], 0, 9}], 9]*\[Delta]^9], {k, 1, Length[arg]}]]; ]; out]

Simplify[Series[Denominator[Coefficient[PP[0, 0][z], z, 3]] /. replqrr /. ee -> e\[Alpha] /. \[Alpha][ll_] -> (\[Epsilon][1]/3 + \[Epsilon][2]/3)/(1 - Exp[2*Pi*(I/3)*ll]*\[Delta]), {\[Delta], 0, 9}]]

FullSimplify[Normal[%%/%]]

cPP[0, i_][3] = % /. LLL[0][y] -> LLL[i][y]; 

cPP[0, i_][3] = -(((1 + 27*y)*((\[Epsilon][1]*\[Epsilon][2])/(\[Epsilon][1] + \[Epsilon][2])^3)^(3/2)*((\[Epsilon][1] + \[Epsilon][2])^2*(3753*y*(-2 + 27*y)*\[Epsilon][1]^6 + 81*y*(-418 + 4833*y)*\[Epsilon][1]^5*\[Epsilon][2] - 6*(160 + 729*y*(-58 + 53*y))*\[Epsilon][1]^4*\[Epsilon][2]^2 + (59200 - 81*y*(31586 + 85059*y))*\[Epsilon][1]^3*\[Epsilon][2]^3 - 6*(160 + 729*y*(-58 + 53*y))*\[Epsilon][1]^2*\[Epsilon][2]^4 + 81*y*(-418 + 4833*y)*\[Epsilon][1]*\[Epsilon][2]^5 + 3753*y*(-2 + 27*y)*\[Epsilon][2]^6) + 3*(\[Epsilon][1] + \[Epsilon][2])*(3753*y*(-5 + 108*y)*\[Epsilon][1]^6 + 81*y*(-1055 + 19872*y)*\[Epsilon][1]^5*\[Epsilon][2] - 6*(320 + 81*y*(-1475 + 5328*y))*\[Epsilon][1]^4*\[Epsilon][2]^2 + (127360 - 81*y*(112195 + 273816*y))*\[Epsilon][1]^3*\[Epsilon][2]^3 - 6*(320 + 81*y*(-1475 + 5328*y))*\[Epsilon][1]^2*\[Epsilon][2]^4 + 81*y*(-1055 + 19872*y)*\[Epsilon][1]*\[Epsilon][2]^5 + 3753*y*(-5 + 108*y)*\[Epsilon][2]^6)*LLL[0][y] + 27*(3753*y*(-1 + 54*y)*\[Epsilon][1]^6 + 243*y*(-73 + 3402*y)*\[Epsilon][1]^5*\[Epsilon][2] - 2*(160 + 27*y*(-3559 + 43686*y))*\[Epsilon][1]^4*\[Epsilon][2]^2 + (22720 + 27*y*(-119549 + 60426*y))*\[Epsilon][1]^3*\[Epsilon][2]^3 - 2*(160 + 27*y*(-3559 + 43686*y))*\[Epsilon][1]^2*\[Epsilon][2]^4 + 243*y*(-73 + 3402*y)*\[Epsilon][1]*\[Epsilon][2]^5 + 3753*y*(-1 + 54*y)*\[Epsilon][2]^6)*LLL[0][y]^2))/(466560*Sqrt[3]*y*\[Epsilon][1]^5*\[Epsilon][2]^5*((1 + 27*y*(-7 + 27*y))*(\[Epsilon][1] + \[Epsilon][2])^2 + 3*(2 + 135*y*(-4 + 27*y))*(\[Epsilon][1] + \[Epsilon][2])*LLL[0][y] + 9*(1 + 54*y*(-8 + 135*y))*LLL[0][y]^2))) /. LLL[0][y] -> LLL[i][y]; 

(* ::Text:: The R-matrix in the fibrewise limit and in minimal form, finally. It\[CloseCurlyQuote]s expressed in a mixed basis Subscript[P, a*i]=Subscript[Coeff, Subscript[e, i]]*R[H^a]: we pick the flat basis for the argument, and the normalised canonical for the image. *)

PPdiag[0, i_][z_] = Sum[cPP[0, i][k]*z^k, {k, 0, ZMAX}]; 

PPdiag[1, i_][z_] = Block[{arg = (LLL[i][y]*PPdiag[0, i][z] + z*y*D[PPdiag[0, i][z], y])/c1[y] /. LLDerrepldiag}, Sum[Simplify[LLpowreddiag[Coefficient[arg, z, k], LLL[i][y]]*z^k], {k, 0, ZMAX}]]; 

PPdiag[2, i_][z_] = Block[{arg = (LLL[i][y]*PPdiag[1, i][z] + z*y*D[PPdiag[1, i][z], y] - d2[y]*PPdiag[1, i][z])/c2[y] /. LLDerrepldiag}, Sum[Simplify[LLpowreddiag[Coefficient[arg, z, k], LLL[i][y]]*z^k], {k, 0, ZMAX}]]; 

(* ::Text:: We are now free to take the fibrewise limit in the following. *)

\[Alpha][ll_] = (\[Epsilon][1] + \[Epsilon][2])/3; ee = e\[Alpha]; 

(* ::Text:: Some checks. Verify that at z=0 we recover the Jacobian from the flat frame to the normalised canonical one:  *)

ReplDenLL = Simplify[Table[(3*ee[3] + ee[2]*LLL[i][y])*(9/(\[Epsilon][1] + \[Epsilon][2])^2) -> (9/(\[Epsilon][1] + \[Epsilon][2])^2)*Sqrt[-3*ee[3]*(1 + 27*y)*LLL[i][y]*(LLL[i][y] - LLL[Mod[i + 1, 3]][y])*(LLL[i][y] - LLL[Mod[i + 2, 3]][y])], {i, 0, 2}]]

FullSimplify[Factor[Table[(PPdiag[ii, jj][0]/\[CapitalPsi][[jj + 1,ii + 1]])^2 //. bigrepl /. LL[ll_] -> LLL[ll][y] /. ll -> L /. d2[y_] -> ee[1]*((1/2)*c2[y] - (1/2)*L[y]^3) /. c2[y] -> L[y]^3/c1[y]^2, {ii, 0, 2}, {jj, 0, 2}]] /. ReplDenLL]

(* ::Text:: Good. Computing dilaton leaf, marked leaf, and edge terms.  *)

Dynamic[{i, n}]

Do[Dilaton[i, n] = Coefficient[-PPdiag[0, i][-z], z, n - 1], {i, 0, 2}, {n, 1, ZMAX + 1}]

Do[Leaf[i, n, a] = Coefficient[PPdiag[a, i][-z] /. d2[y_] -> ee[1]*((1/2)*c2[y] - (1/2)*L[y]^3) /. c2[y] -> L[y]^3/c1[y]^2, z, n], {i, 0, 2}, {n, 0, ZMAX}, {a, 0, 2}]

(* ::Text:: To compute the edge term, we first compute id - SuperStar[P[-w]]*P[-z] *)

Do[PreEdgeTerm[i, j] = KroneckerDelta[i, j] - Sum[PPdiag[a, i][-ww]*Inverse[\[Eta]][[a + 1,b + 1]]*PPdiag[b, j][-zz], {a, 0, 2}, {b, 0, 2}] /. d2[y_] -> ee[1]*((1/2)*c2[y] - (1/2)*L[y]^3) /. c2[y] -> L[y]^3/c1[y]^2 //. bigrepl /. LL[ll_] -> LLL[ll][y] /. ll -> L, {i, 0, 2}, {j, 0, 2}]; 

(* ::Text:: and then divide by (z+w). At the level of coefficients, this reads: *)

Dynamic[{i, j, m, n}]

AbsoluteTiming[Do[Block[{precoeff = CoefficientList[PreEdgeTerm[i, j], {ww, zz}]}, Do[EdgeTerm[i, j, m, n] = Together[Sum[(-1)^k*precoeff[[m + k + 2,n - k + 1]], {k, 0, n}]]; , {m, 0, ZMAX - 2}, {n, 0, ZMAX - 2}]; ]; , {j, 0, 1}, {i, 0, 0}]]

AbsoluteTiming[Do[Block[{precoeff = CoefficientList[PreEdgeTerm[i, j], {ww, zz}]}, Do[EdgeTerm[i, j, m, n] = Together[Sum[(-1)^k*precoeff[[m + k + 2,n - k + 1]], {k, 0, n}]]; , {m, 0, ZMAX - 1}, {n, 0, 0}]; ]; , {j, 0, 1}, {i, 0, 0}]]

(* ::Text:: Representing some terms below in minimal form. *)

AbsoluteTiming[EdgeTerm[0, 0, 0, 0] = LLpowreddiag[EdgeTerm[0, 0, 0, 0], LLL[0][y]]; ]

AbsoluteTiming[EdgeTerm[0, 0, 1, 0] = LLpowreddiag[EdgeTerm[0, 0, 1, 0], LLL[0][y]]; ]

AbsoluteTiming[EdgeTerm[0, 0, 2, 0] = LLpowreddiag[EdgeTerm[0, 0, 2, 0], LLL[0][y]]; ]

AbsoluteTiming[EdgeTerm[0, 1, 0, 0] = LLpowreddiag[LLpowreddiag[EdgeTerm[0, 1, 0, 0], LLL[0][y]], LLL[1][y]]; ]

AbsoluteTiming[EdgeTerm[0, 1, 1, 0] = LLpowreddiag[LLpowreddiag[EdgeTerm[0, 1, 1, 0], LLL[0][y]], LLL[1][y]]; ]

AbsoluteTiming[EdgeTerm[1, 1, 0, 0] = LLpowreddiag[EdgeTerm[1, 1, 0, 0], LLL[1][y]]; ]

AbsoluteTiming[EdgeTerm[0, 0, 1, 1] = LLpowreddiag[EdgeTerm[0, 0, 1, 1], LLL[0][y]]; ]

AbsoluteTiming[EdgeTerm[0, 1, 1, 1] = LLpowreddiag[LLpowreddiag[EdgeTerm[0, 1, 1, 1], LLL[0][y]], LLL[1][y]]; ]

AbsoluteTiming[EdgeTerm[1, 2, 0, 0] = LLpowreddiag[LLpowreddiag[EdgeTerm[1, 1, 0, 0], LLL[1][y]], LLL[2][y]]; ]

sqrt\[CapitalDelta][i_] = Simplify[Sqrt[\[Epsilon][1]*(\[Epsilon][2]/ee[3])]*(3*ee[3] + ee[2]*LLL[i][y])]

(* ::Subsection:: Stable graph sums *)

(* ::Subsubsection:: some calculations about the odd generator *)

(* ::Text:: All graph terms are rational functions of LLL[i][y], and in the fibrewise limit, they are actually Subscript[S, 3]-invariant (i.e. symmetric) rational functions in them. Since symmetric polynomials in LLL[i][y] are coefficients of polPFL[y, LLL[i][y]], they are in particular rational functions of y. It will be useful in the following to consider Subscript[\[Mu], 3]-invariant (i.e. cyclically symmetric) rational functions of LLL[i][y]: it turns out that these are also rational functions of y. To see it, consider the ideal generated by the symmetric polynomials in Subscript[{LLL[i][y]}, i], i=0,1,2: *)

ngrb = Table[SymmetricPolynomial[k, Table[LLL[i][y], {i, 0, 2}]] - Coefficient[polPFLdiag[y, XX]/(1 + 27*y), XX, 3 - k], {k, 1, 3}]

(* ::Text:: A Groebener basis for the ideal. *)

grb = DeleteCases[Simplify[GroebnerBasis[ngrb, Table[LLL[i][y], {i, 0, 2}]]], 0]

(* ::Text:: We have that C[x, y, z]^Subscript[\[Mu], 3] = C[Subscript[e, 1], Subscript[e, 2], Subscript[e, 3], o]/(o^2=Subscript[e, 1]^2*Subscript[e, 2]^2 - 4*Subscript[e, 2]^3 - 4*Subscript[e, 1]^3*Subscript[e, 3] + 18*Subscript[e, 1]*Subscript[e, 2]*Subscript[e, 3] - 27*Subscript[e, 3]^2): here Subscript[e, i] is the i^th elementary symmetric polynomial, and o[x, y, z] = (x - y)*(x - z)*(y - z) is cyclically invariant and odd under transposition. Let\[CloseCurlyQuote]s figure out what DisplayForm[FormBox[RowBox[{SuperscriptBox["o", "2"], "(", RowBox[{SubscriptBox["L", "0"], ",", SubscriptBox["L", "1"], ",", SubscriptBox["L", "2"]}]}], TraditionalForm]]) looks like  *)

Simplify[PolynomialReduce[((LLL[0][y] - LLL[1][y])*(LLL[0][y] - LLL[2][y])*(LLL[1][y] - LLL[2][y]))^2, grb, Table[LLL[i][y], {i, 0, 2}]][[-1]]]

(* ::Text:: so DisplayForm[FormBox[RowBox[{"o", "(", RowBox[{SubscriptBox["L", "0"], ",", SubscriptBox["L", "1"], ",", SubscriptBox["L", "2"]}]}], TraditionalForm]]), as a function of y, is *)

Simplify[Sqrt[%], \[Epsilon][1] > -\[Epsilon][2] && y > 0]

(* ::Subsubsection:: reprise *)

(* ::Text:: The next function takes as input a cyclically symmetric polynomial arg Nullin {LLL[0][y], LLL[1][y], LLL[2][y]} and writes it as a polynomial in the generators of DisplayForm[FormBox[SuperscriptBox[RowBox[{RowBox[{RowBox[{"C", "[", RowBox[{RowBox[{RowBox[{"LLL", "[", "0", "]"}], "[", "y", "]"}], ",", RowBox[{RowBox[{"LLL", "[", "1", "]"}], "[", "y", "]"}], ",", RowBox[{RowBox[{"LLL", "[", "2", "]"}], "[", "y", "]"}]}]}], "}"}], "]"}], SubscriptBox["\[Mu]", "3"]], TraditionalForm]], and therefore as an algebraic function of y. *)

ToSymPolLL[arg_] := If[arg === 0, 0, Block[{argint = arg, par, exp, pol, sol, out, parodd, odd}, exp = Length[CoefficientList[argint, LLL[0][y]]] - 1; par = Select[Flatten[Table[Partitions[k, 3], {k, 0, 3*exp}], 1], Length[#1] <= exp & ]; parodd = Select[Flatten[Table[Partitions[k, 3], {k, 0, 3*(exp - 1)}], 1], Length[#1] <= exp - 2 & ]; odd = (LLL[0][y] - LLL[1][y])*(LLL[0][y] - LLL[2][y])*(LLL[1][y] - LLL[2][y]); pol = Sum[AA[k]*Product[SymmetricPolynomial[par[[k]][[j]], Table[LLL[i][y], {i, 0, 2}]], {j, 1, Length[par[[k]]]}], {k, 1, Length[par]}] + odd*Sum[AA[k + Length[par]]*Product[SymmetricPolynomial[parodd[[k]][[j]], Table[LLL[i][y], {i, 0, 2}]], {j, 1, Length[parodd[[k]]]}], {k, 1, Length[parodd]}]; sol = Flatten[Solve[CoefficientList[argint - pol, {LLL[0][y], LLL[1][y], LLL[2][y]}] == 0, Table[AA[k], {k, 1, Length[par] + Length[parodd]}]]]; If[sol == {}, Print["Error -- argument is not a cyclically symmetric polynomial in each LLL[i][y]"]; Abort[]]; out = Simplify[Sum[AA[k]*Product[(-1)^par[[k]][[j]]*e\[Alpha][par[[k]][[j]]]*L[y]^3, {j, 1, Length[par[[k]]]}], {k, 1, Length[par]}] + (3*Sqrt[3]*I*((y*(\[Epsilon][1] + \[Epsilon][2])^3)/(1 + 27*y)^2))*Sum[AA[Length[par] + k]*Product[(-1)^parodd[[k]][[j]]*e\[Alpha][parodd[[k]][[j]]]*L[y]^3, {j, 1, Length[parodd[[k]]]}], {k, 1, Length[parodd]}] /. sol]; out]]

(* ::Text:: Same as above, but for cyclically symmetric rational functions in {LLL[0][y], LLL[1][y], LLL[2][y]}. *)

ToSymRatLL[arg_] := Block[{frac}, frac = Together[arg]; ToSymPolLL[Numerator[frac]]/ToSymPolLL[Denominator[frac]]]

(* ::Text:: Variables such as EdgeTerm[i,j,m,n] soon take up hundreds of Mb of RAM, and graph sums involving symmetric functions of them are too cumbersome for ToSymRatLL and ToSymPolLL to swallow. An efficient workaround is implemented here: we generate a table of cyclically symmetric combination of monomials in (LLL[0][y], LLL[1][y], LLL[2][y]), up to order MONMAX in each variable.  *)

MONMAX = 12

CyclicProj[arg_] := (1/3)*Sum[arg /. LLL[ll_][y] -> LLL[Mod[ll + kk, 3]][y], {kk, 1, 3}]

(* ::Text:: The next routine is commented out -- its result is input in the next section. *)

Null

(* ::Text:: This routine is the heart of the computations of stable graph contributions. It takes arg a rational function of Subscript[LLL[i][y], i] as input, and it considers its cyclic symmetrisation. It first computes the denominator in the symmetrisation as a function of y by invoking ToSymPolLL -- this is always relatively fast -- and then the numerator, which is often extremely cumbersome. In order to do this, we expand it as a (very large) polynomial of LLL[i][y] and replace each monomial using the list moncycproj above to compute the cyclically-invariant projection. The resulting polynomial in y is usually too big for Mathematica to Simplify (up to hundreds of MB). The trick here is to use the fact that 1) the denominator is always of the form (1+27 DisplayForm[FormBox[SuperscriptBox[RowBox[{"y", ")"}], "n"], TraditionalForm]] for some very large n; 2) the numerator contains (1+27 DisplayForm[FormBox[SuperscriptBox[RowBox[{"y", ")"}], RowBox[{"n", "-", "deg\[CapitalDelta]"}]], TraditionalForm]] as a factor, where the argument deg\[CapitalDelta] is the order of the pole of arg at the discriminant; 3) as a result, (1+27 DisplayForm[FormBox[SuperscriptBox[RowBox[{"y", ")"}], "deg\[CapitalDelta]"], TraditionalForm]] x numerator/denominator is a polynomial in y of relatively small degree degy: to compute it, it suffices to interpolate the crazy-big expression for the numerator at a small number (=degy+1) of values for the argument y. *)

CyclicQuotOpt[arg_, degy_, deg\[CapitalDelta]_] := Block[{num, den, denc, summand, sum, degLL}, num = Numerator[arg]; den = Denominator[arg]; denc = If[Head[den] == Times, Product[ToSymPolLL[Product[den[[m]] /. LLL[ll_] -> LLL[Mod[ll + kk, 3]], {kk, 0, 2}]], {m, 1, Length[den]}], ToSymPolLL[den]]; Print["Cyclic symmetrisation of the denominator OK. Result: "]; Print[denc]; summand = num*(den /. LLL[ll_][y] -> LLL[Mod[ll + 1, 3]][y])*(den /. LLL[ll_][y] -> LLL[Mod[ll + 2, 3]][y]); degLL = Max[Table[Exponent[summand, LLL[i][y]], {i, 0, 2}]]; Print[StringJoin["Max degree in LLL[i] is: ", ToString[degLL], "."]]; If[degLL > MONMAX, Print["Degree exceeds bounds. Try using a higher value for MONMAX. Aborting..."]; Abort[]]; Print["Starting cyclic symmetrisation of the numerator..."]; sum = Sum[Factor[Factor[Coefficient[Coefficient[Coefficient[(1 + 27*y)^deg\[CapitalDelta]*(summand/denc), LLL[2][y], m[2]], LLL[1][y], m[1]], LLL[0][y], m[0]]]*moncycproj[[m[0] + 1,m[1] + 1,m[2] + 1]]] /. Derivative[1][c1][y] -> cc1p /. c1[y] -> cc1, {m[0], 0, degLL}, {m[1], 0, degLL}, {m[2], 0, degLL}]; Print["Cyclic symmetrisation of the numerator OK. Interpolating..."]; Factor[InterpolatingPolynomial[Table[sum /. y -> n, {n, 1, degy + 1}], y]/(1 + 27*y)^deg\[CapitalDelta] /. cc1 -> c1[y] /. cc1p -> Derivative[1][c1][y]]]

(* ::Text:: Symplecticity checks (commented out): *)

Null

Null

(* ::Subsubsection:: replacements for cyclically symmetrised monomials -- run this *)

MONMAX = 12

Null

