(* ::Subsection:: Small z-asymptotics of the I-function *)

(* ::Text:: The algebraic relation for the canonical coordinates on the small quantum cohomology locus, arising from the leading order in z of the expansion of the solution of the equivariant PF equation. *)

lpol = polPF /. ee -> e\[Alpha] /. XX[i_] -> XX^i /. ll -> L

(* ::Text:: y-expansion of the solutions of lpol = 0, in terms of indeterminates \[Mu]pexp. *)

\[Mu]p[i_, y_] = Sum[\[Mu]pexp[i, n]*y^n, {n, 1, DMAX}]

(* ::Text:: Solving for \[Mu]pexp. *)

Do[\[Mu]repl[i] = Block[{explpol, out = {}}, explpol = Series[lpol /. XX -> -\[Alpha][i] + y*D[\[Mu]p[i, y], y], {y, 0, 2*DMAX}]; Do[AppendTo[out, Flatten[Solve[SeriesCoefficient[explpol, k] == 0, \[Mu]pexp[i, k]]]], {k, 1, DMAX}]; Simplify[Flatten[out]]], {i, 0, 2}]

Do[\[Mu]psol[i, y_] = Normal[Simplify[Series[\[Mu]p[i, y] //. \[Mu]repl[i], {y, 0, DMAX}]]], {i, 0, 2}]

Series[lpol /. XX -> -\[Alpha][0] + y*D[\[Mu]psol[0, y], y], {y, 0, DMAX}]

(* ::Text:: Small z-asymptotics of the I-function. *)

ZMAX = 4; 

IAs[i_][y_, z_] := (1/Sqrt[3*\[Epsilon][1]*\[Epsilon][2]*\[Alpha][i]*(\[Alpha][i] - \[Alpha][Mod[i + 1, 3]])*(\[Alpha][i] - \[Alpha][Mod[i + 2, 3]])])*Exp[\[Mu][i, y]/z]*Sum[SS[0, i, k, n]*z^k*y^n, {k, 0, ZMAX}, {n, 0, DMAX}]

(* ::Text:: Plugging that into the Picard-Fuchs equations. *)

PFasp[i_] := Block[{coeff = CoefficientList[Series[(z*DY + \[Alpha][0] - \[Alpha][i])*(z*DY + \[Alpha][1] - \[Alpha][i])*(z*DY + \[Alpha][2] - \[Alpha][i]), {DY, 0, 3}], DY], coeff2 = CoefficientList[Series[(3*z*DY - 3*\[Alpha][i])*(3*z*DY + z - 3*\[Alpha][i])*(3*z*DY + 2*z - 3*\[Alpha][i]), {DY, 0, 3}], DY]}, Sum[coeff[[n + 1]]*D[IAs[i][Exp[Y], z], {Y, n}], {n, 0, 3}] + y*Sum[coeff2[[n + 1]]*D[IAs[i][Exp[Y], z], {Y, n}], {n, 0, 3}] /. Y -> Log[y]]

(* ::Text:: Small z and y expansion of the PF equations. Note that these are linear in the indeterminates SS[0,i,k,m] *)

Do[eq[i] = Take[CoefficientList[Expand[PFasp[i]*Exp[-\[Mu][i, y]/z]] /. \[Mu] -> \[Mu]p //. \[Mu]repl[i], {z, y}], {1, DMAX + 1}, {1, DMAX + 1}], {i, 0, 2}]; 

(* ::Text:: The constant part in SS[0,i,k,m]. We normalise SS[0,i,k,0]=qrrc[i,k] (qrrc= \[OpenCurlyDoubleQuote]Quantum Riemann Roch constant\[CloseCurlyDoubleQuote] term). *)

Do[v[i] = Simplify[-Flatten[eq[i]] /. SS[0, l_, k_, 0] -> qrrc[l, k] /. SS[0, l_, k_, m_] -> 0]; , {i, 0, 2}]; 

(* ::Text:: The matrix of coefficients of SS[0, i, k, m] *)

Do[mm[i] = Simplify[Block[{eqq = Flatten[eq[i]]}, Table[Flatten[Table[D[eqq[[n]], {SS[0, i, k, m], 1}], {k, 0, DMAX}, {m, 1, DMAX}]], {n, 1, Length[eqq]}]]]; , {i, 0, 2}]

(* ::Text:: Solving for SS[0,i,k,m]. *)

AbsoluteTiming[Do[solSS[i] = LinearSolve[mm[i], v[i]], {i, 0, 2}]; ]

AbsoluteTiming[Do[SSrepl[0, i] = Simplify[Together[Table[Flatten[Table[SS[0, i, k, m], {k, 0, DMAX}, {m, 1, DMAX}]][[n]] -> solSS[i][[n]], {n, 1, Length[solSS[i]]}]]], {i, 0, 2}]]

