replqrr = Block[{ser}, Flatten[Table[qrrc[i, k] -> SeriesCoefficient[Series[Exp[Sum[Qrrc[i, k]*z^(2*k + 1), {k, 0, 3}]], {z, 0, DMAX + 1}], k], {i, 0, 2}, {k, 0, DMAX + 1}]]]; 

