w[i_, j_] := If[j < 3, If[i != j, \[Alpha][j] - \[Alpha][i], 3*\[Alpha][i]], -\[Epsilon][j - 2]]

QRRc[i_, k_] := (BernoulliB[2*k + 2]/(2*k + 2)/(2*k + 1))*Sum[w[i, j]^(2*k + 1), {j, 0, 4}]

